def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove expired entries first (optional, but helps with correctness)
            # Actually we only need to check if specific entries are expired when accessed

            # If key already exists, remove it to re-add it at the end (most recently used)
            if key in cache:
                del cache[key]
            else:
                # Key is new, check if we need to evict
                if len(cache) >= capacity:
                    # Evict the least recently used (first item in OrderedDict)
                    cache.popitem(last=False)

            cache[key] = (value, t)

        elif op[0] == 'get':
            _, t, key = op

            if key in cache:
                value, write_time = cache[key]
                # Check if entry has expired
                if t >= write_time + ttl:
                    # Entry is expired, remove it and return -1
                    del cache[key]
                    results.append(-1)
                else:
                    # Entry is valid, return it and mark as most recently used
                    del cache[key]
                    cache[key] = (value, write_time)
                    results.append(value)
            else:
                # Key not in cache
                results.append(-1)

    return results

